using System;
using System.Collections.Immutable;
using System.Linq;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00002 : ControllerTestBase
    {
        [TestMethod]
        public void ApiController_Attribute_Have_To_Be_Set()
        {
        var missingApiControllerAttributes = (from controller in Controllers
                                              where controller.Attributes.All(a => a.Name.DoesNotContain("ApiController"))
                                              select new
                                              {
                                                  ErrorClass = controller.FullQualifiedName,
                                                  Error = $@"
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Class:       {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: 

{controller.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample:

[ApiController]
{controller.SyntaxTree.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                              }).ToImmutableList();

            Assert.IsTrue(missingApiControllerAttributes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00002

Missing [ApiController] declaration for on controller detected. Findings {missingApiControllerAttributes.Count}': {Environment.NewLine}{missingApiControllerAttributes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }


